import{_ as l,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"RGW Refactoring Meeting 2023-08-16","description":"","frontmatter":{"title":"RGW Refactoring Meeting 2023-08-16","date":"2023-08-16T00:00:00.000Z","updated":"2023-08-17T00:00:00.000Z","tags":["Ceph","RGW","性能计数器","Prometheus","S3测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/RGW_Refactoring_Meeting_2023-08-16.md","filePath":"posts/2023/RGW_Refactoring_Meeting_2023-08-16.md","lastUpdated":1780459816000}'),o={name:"posts/2023/RGW_Refactoring_Meeting_2023-08-16.md"};function r(s,e,n,u,d,p){return i(),a("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>本次会议主要讨论了Ali关于标记性能计数器(labeled perf counters)和RGW（RADOS Gateway）集成的进展，以及Tobias在处理S3测试中粗选项请求的工作。</p><h4 id="主要讨论内容" tabindex="-1">主要讨论内容： <a class="header-anchor" href="#主要讨论内容" aria-label="Permalink to &quot;主要讨论内容：&quot;">​</a></h4><ol><li><p><strong>Ali的工作进展</strong>：</p><ul><li>Ali提交了一个PR，包含性能计数器的初始草案，并对RGW的前端操作计数器进行了标记。</li><li>计划进行更大规模的测试，并欢迎反馈。</li><li>PR中创建了多个性能计数器实例，针对不同的操作（如put, get, delete等）。</li></ul></li><li><p><strong>性能计数器实例的合并</strong>：</p><ul><li>Casey建议将所有前端操作计数器合并到一个实例中，以便按桶名或用户名进行缓存。</li><li>Ali解释了当前设计的原因，主要是为了未来的灵活性和多站点计数器的集成。</li></ul></li><li><p><strong>缓存和Prometheus集成</strong>：</p><ul><li>讨论了缓存驱逐的工作原理和配置。</li><li>确认了每个RGW节点需要一个单独的exporter，用于将计数器数据发送到Prometheus。</li></ul></li><li><p><strong>下一步行动计划</strong>：</p><ul><li>Ali将继续测试并优化性能计数器的实现。</li><li>Mark和Ali将在Folio实验室的机器上进行大规模测试，以验证exporter和Prometheus的集成性能。</li></ul></li><li><p><strong>其他议题</strong>：</p><ul><li>Tobias分享了关于处理粗选项请求的工作进展，并寻求反馈。</li><li>讨论了S3测试的默认认证路径（V2 vs V4），并计划进一步验证和优化。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>Ali将继续优化性能计数器的实现，并进行大规模测试。</li><li>Tobias将寻找更合适的位置来放置认证验证逻辑。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>Ali和Mark将进行大规模测试，以验证性能计数器和Prometheus的集成。</li><li>Tobias将继续优化S3测试和认证逻辑的实现。</li></ul>',9)])])}const c=l(o,[["render",r]]);export{_ as __pageData,c as default};
